package store

import (
	"database/sql"
	"errors"

	"lms/backend/internal/models"
)

const borrowSelect = "SELECT br.id,br.reader_id,br.book_id,br.borrow_date,br.due_date," +
	"br.return_date,br.renew_count,br.status,br.fine," +
	"b.title,b.author,r.name,r.reader_no " +
	"FROM borrow_records br JOIN books b ON br.book_id=b.id " +
	"JOIN readers r ON br.reader_id=r.id "

func scanBorrow(sc interface{ Scan(...any) error }) (models.BorrowRecord, error) {
	var r models.BorrowRecord
	var returnDate sql.NullString
	err := sc.Scan(&r.ID, &r.ReaderID, &r.BookID, &r.BorrowDate, &r.DueDate,
		&returnDate, &r.RenewCount, &r.Status, &r.Fine,
		&r.Title, &r.Author, &r.ReaderName, &r.ReaderNo)
	r.ReturnDate = returnDate.String
	return r, err
}

// CreateBorrow 写入借阅记录并返回主键。
func (s *Store) CreateBorrow(r *models.BorrowRecord) error {
	res, err := s.db.Exec(
		"INSERT INTO borrow_records(reader_id,book_id,borrow_date,due_date,renew_count,status,fine) "+
			"VALUES(?,?,?,?,?,?,?)",
		r.ReaderID, r.BookID, r.BorrowDate, r.DueDate, r.RenewCount, r.Status, r.Fine)
	if err != nil {
		return err
	}
	id, _ := res.LastInsertId()
	r.ID = id
	return nil
}

// GetBorrow 按主键查询借阅记录（含关联信息）。
func (s *Store) GetBorrow(id int64) (*models.BorrowRecord, error) {
	row := s.db.QueryRow(borrowSelect+"WHERE br.id=?", id)
	r, err := scanBorrow(row)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, ErrNotFound
	}
	if err != nil {
		return nil, err
	}
	return &r, nil
}

func (s *Store) listBorrow(q string, args ...any) ([]models.BorrowRecord, error) {
	rows, err := s.db.Query(q, args...)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []models.BorrowRecord{}
	for rows.Next() {
		r, err := scanBorrow(rows)
		if err != nil {
			return nil, err
		}
		out = append(out, r)
	}
	return out, rows.Err()
}

// ListActive 查询未归还借阅；readerID 为 nil 时查询全部。
func (s *Store) ListActive(readerID *int64) ([]models.BorrowRecord, error) {
	if readerID != nil {
		return s.listBorrow(borrowSelect+"WHERE br.status='borrowed' AND br.reader_id=? ORDER BY br.due_date",
			*readerID)
	}
	return s.listBorrow(borrowSelect + "WHERE br.status='borrowed' ORDER BY br.due_date")
}

// ListHistory 查询已归还历史；readerID 为 nil 时查询全部。
func (s *Store) ListHistory(readerID *int64) ([]models.BorrowRecord, error) {
	if readerID != nil {
		return s.listBorrow(borrowSelect+"WHERE br.status='returned' AND br.reader_id=? ORDER BY br.return_date DESC",
			*readerID)
	}
	return s.listBorrow(borrowSelect + "WHERE br.status='returned' ORDER BY br.return_date DESC")
}

// MarkReturned 标记归还、归还日期与罚款。
func (s *Store) MarkReturned(id int64, returnDate string, fine float64) error {
	_, err := s.db.Exec(
		"UPDATE borrow_records SET status='returned',return_date=?,fine=? WHERE id=?",
		returnDate, fine, id)
	return err
}

// MarkRenewed 更新续借次数与新应还日期。
func (s *Store) MarkRenewed(id int64, dueDate string, renewCount int) error {
	_, err := s.db.Exec(
		"UPDATE borrow_records SET renew_count=?,due_date=? WHERE id=?", renewCount, dueDate, id)
	return err
}

// CountActive 统计读者在借数量。
func (s *Store) CountActive(readerID int64) (int, error) {
	var n int
	err := s.db.QueryRow(
		"SELECT COUNT(*) FROM borrow_records WHERE reader_id=? AND status='borrowed'", readerID).Scan(&n)
	return n, err
}

// CountOverdue 统计读者逾期数量。
func (s *Store) CountOverdue(readerID int64, today string) (int, error) {
	var n int
	err := s.db.QueryRow(
		"SELECT COUNT(*) FROM borrow_records WHERE reader_id=? AND status='borrowed' AND due_date<?",
		readerID, today).Scan(&n)
	return n, err
}

// AddLog 写入操作日志。
func (s *Store) AddLog(userID *int64, username, action, detail, createdAt string) error {
	_, err := s.db.Exec(
		"INSERT INTO operation_logs(user_id,username,action,detail,created_at) VALUES(?,?,?,?,?)",
		userID, username, action, detail, createdAt)
	return err
}

// Dashboard 返回控制台汇总指标。
func (s *Store) Dashboard(today string) (*models.Dashboard, error) {
	d := &models.Dashboard{}
	one := func(q string, p ...any) (int, error) {
		var n int
		return n, s.db.QueryRow(q, p...).Scan(&n)
	}
	var err error
	if d.BookKinds, err = one("SELECT COUNT(*) FROM books"); err != nil {
		return nil, err
	}
	if d.BookCopies, err = one("SELECT COALESCE(SUM(total_qty),0) FROM books"); err != nil {
		return nil, err
	}
	if d.Readers, err = one("SELECT COUNT(*) FROM readers"); err != nil {
		return nil, err
	}
	if d.Borrowed, err = one("SELECT COUNT(*) FROM borrow_records WHERE status='borrowed'"); err != nil {
		return nil, err
	}
	if d.Overdue, err = one(
		"SELECT COUNT(*) FROM borrow_records WHERE status='borrowed' AND due_date<?", today); err != nil {
		return nil, err
	}
	return d, nil
}

// CategoryStats 返回分类馆藏统计。
func (s *Store) CategoryStats() ([]models.CategoryStat, error) {
	rows, err := s.db.Query(
		"SELECT c.name,COUNT(b.id),COALESCE(SUM(b.total_qty),0) " +
			"FROM categories c LEFT JOIN books b ON b.category_id=c.id GROUP BY c.id ORDER BY 3 DESC")
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []models.CategoryStat{}
	for rows.Next() {
		var c models.CategoryStat
		if err := rows.Scan(&c.Name, &c.Kinds, &c.Copies); err != nil {
			return nil, err
		}
		out = append(out, c)
	}
	return out, rows.Err()
}

// HotBooks 返回借阅热度排行。
func (s *Store) HotBooks(limit int) ([]models.HotBook, error) {
	rows, err := s.db.Query(
		"SELECT b.title,b.author,COUNT(br.id) FROM books b "+
			"LEFT JOIN borrow_records br ON br.book_id=b.id GROUP BY b.id ORDER BY 3 DESC,b.id LIMIT ?", limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []models.HotBook{}
	for rows.Next() {
		var h models.HotBook
		if err := rows.Scan(&h.Title, &h.Author, &h.Times); err != nil {
			return nil, err
		}
		out = append(out, h)
	}
	return out, rows.Err()
}

// RecentLogs 返回最近操作日志。
func (s *Store) RecentLogs(limit int) ([]models.OperationLog, error) {
	rows, err := s.db.Query(
		"SELECT id,user_id,username,action,detail,created_at FROM operation_logs ORDER BY id DESC LIMIT ?", limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	out := []models.OperationLog{}
	for rows.Next() {
		var l models.OperationLog
		var uid sql.NullInt64
		if err := rows.Scan(&l.ID, &uid, &l.Username, &l.Action, &l.Detail, &l.CreatedAt); err != nil {
			return nil, err
		}
		if uid.Valid {
			id := uid.Int64
			l.UserID = id
		}
		out = append(out, l)
	}
	return out, rows.Err()
}

// Package store 是持久化适配器：基于 SQLite 实现 service 层定义的仓储端口。
package store

import (
	"database/sql"
	"fmt"

	_ "modernc.org/sqlite" // 纯 Go SQLite 驱动，无需 CGO
)

// Store 持有数据库连接并实现全部仓储方法。
type Store struct {
	db *sql.DB
}

// New 打开（必要时创建）数据库并执行建表与种子数据初始化。
func New(dbPath string) (*Store, error) {
	db, err := sql.Open("sqlite", dbPath)
	if err != nil {
		return nil, fmt.Errorf("打开数据库失败: %w", err)
	}
	db.SetMaxOpenConns(1) // SQLite 单写，避免锁竞争
	if _, err := db.Exec(schema); err != nil {
		return nil, fmt.Errorf("建表失败: %w", err)
	}
	s := &Store{db: db}
	if err := s.seedIfEmpty(); err != nil {
		return nil, err
	}
	return s, nil
}

// Close 关闭数据库连接。
func (s *Store) Close() error { return s.db.Close() }

const schema = `
CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    username TEXT UNIQUE NOT NULL,
    password_hash TEXT NOT NULL,
    role TEXT NOT NULL CHECK(role IN ('admin','reader')),
    real_name TEXT,
    status TEXT NOT NULL DEFAULT 'active' CHECK(status IN ('active','disabled')),
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS readers (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    reader_no TEXT UNIQUE NOT NULL,
    name TEXT NOT NULL,
    phone TEXT,
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS categories (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT UNIQUE NOT NULL
);
CREATE TABLE IF NOT EXISTS books (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    isbn TEXT,
    title TEXT NOT NULL,
    author TEXT,
    publisher TEXT,
    category_id INTEGER REFERENCES categories(id),
    location TEXT,
    total_qty INTEGER NOT NULL DEFAULT 1,
    available_qty INTEGER NOT NULL DEFAULT 1,
    created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS borrow_records (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    reader_id INTEGER NOT NULL REFERENCES readers(id),
    book_id INTEGER NOT NULL REFERENCES books(id),
    borrow_date TEXT NOT NULL,
    due_date TEXT NOT NULL,
    return_date TEXT,
    renew_count INTEGER NOT NULL DEFAULT 0,
    status TEXT NOT NULL DEFAULT 'borrowed' CHECK(status IN ('borrowed','returned')),
    fine REAL NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS operation_logs (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    user_id INTEGER,
    username TEXT,
    action TEXT NOT NULL,
    detail TEXT,
    created_at TEXT NOT NULL
);
`

package store

import (
	"database/sql"
	"time"

	"lms/backend/internal/models"

	"golang.org/x/crypto/bcrypt"
)

func nowStr() string { return time.Now().Format("2006-01-02 15:04:05") }

func hashBcrypt(pwd string) string {
	b, _ := bcrypt.GenerateFromPassword([]byte(pwd), bcrypt.DefaultCost)
	return string(b)
}

// seedIfEmpty 在数据库首次创建时写入默认账号、分类、图书与示例借阅。
func (s *Store) seedIfEmpty() error {
	var n int
	if err := s.db.QueryRow("SELECT COUNT(*) FROM users").Scan(&n); err != nil {
		return err
	}
	if n > 0 {
		return nil
	}
	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer func() { _ = tx.Rollback() }()

	// 管理员
	_, err = tx.Exec(
		"INSERT INTO users(username,password_hash,role,real_name,status,created_at) VALUES(?,?,?,?,?,?)",
		"admin", hashBcrypt("admin123"), "admin", "系统管理员", "active", nowStr())
	if err != nil {
		return err
	}
	// 示例读者
	res, err := tx.Exec(
		"INSERT INTO users(username,password_hash,role,real_name,status,created_at) VALUES(?,?,?,?,?,?)",
		"reader", hashBcrypt("reader123"), "reader", "张同学", "active", nowStr())
	if err != nil {
		return err
	}
	uid, _ := res.LastInsertId()
	_, err = tx.Exec(
		"INSERT INTO readers(user_id,reader_no,name,phone,created_at) VALUES(?,?,?,?,?)",
		uid, "R2023001", "张同学", "13800000000", nowStr())
	if err != nil {
		return err
	}
	var readerID int64
	err = tx.QueryRow("SELECT id FROM readers WHERE reader_no='R2023001'").Scan(&readerID)
	if err != nil {
		return err
	}

	// 分类
	cats := []string{"计算机", "文学", "历史", "自然科学", "艺术", "哲学"}
	catID := map[string]int64{}
	for _, c := range cats {
		r, err := tx.Exec("INSERT INTO categories(name) VALUES(?)", c)
		if err != nil {
			return err
		}
		id, _ := r.LastInsertId()
		catID[c] = id
	}

	// 图书
	books := []struct {
		isbn, title, author, publisher, cat, loc string
		qty                                       int
	}{
		{"9787111213826", "软件工程：实践者的研究方法", "Roger S. Pressman", "机械工业出版社", "计算机", "N502-A01", 5},
		{"9787115428028", "Python编程：从入门到实践", "Eric Matthes", "人民邮电出版社", "计算机", "N502-A02", 4},
		{"9787302259862", "算法导论", "Thomas H. Cormen", "清华大学出版社", "计算机", "N502-A03", 3},
		{"9787020008735", "红楼梦", "曹雪芹", "人民文学出版社", "文学", "N503-B01", 6},
		{"9787020008728", "西游记", "吴承恩", "人民文学出版社", "文学", "N503-B02", 6},
		{"9787101003048", "史记", "司马迁", "中华书局", "历史", "N504-C01", 3},
		{"9787535732224", "时间简史", "Stephen Hawking", "湖南科学技术出版社", "自然科学", "N505-D01", 4},
		{"9787544270878", "万物简史", "Bill Bryson", "接力出版社", "自然科学", "N505-D02", 3},
		{"9787102048161", "中国艺术史", "苏立文", "上海人民出版社", "艺术", "N506-E01", 2},
		{"9787544720885", "西方哲学史", "Bertrand Russell", "译林出版社", "哲学", "N505-D03", 3},
	}
	bookID := map[string]int64{}
	for _, b := range books {
		r, err := tx.Exec(
			"INSERT INTO books(isbn,title,author,publisher,category_id,location,total_qty,available_qty,created_at) "+
				"VALUES(?,?,?,?,?,?,?,?,?)",
			b.isbn, b.title, b.author, b.publisher, catID[b.cat], b.loc, b.qty, b.qty, nowStr())
		if err != nil {
			return err
		}
		id, _ := r.LastInsertId()
		bookID[b.title] = id
	}

	// 示例借阅：一本正常（5天前），一本逾期（40天前，应还10天前）
	today := time.Now()
	b1 := today.AddDate(0, 0, -5)
	d1 := b1.AddDate(0, 0, 30)
	if _, err := tx.Exec(
		"INSERT INTO borrow_records(reader_id,book_id,borrow_date,due_date,renew_count,status,fine) VALUES(?,?,?,?,?,?,?)",
		readerID, bookID["Python编程：从入门到实践"], b1.Format("2006-01-02"), d1.Format("2006-01-02"), 0, "borrowed", 0); err != nil {
		return err
	}
	if _, err := tx.Exec("UPDATE books SET available_qty=available_qty-1 WHERE id=?",
		bookID["Python编程：从入门到实践"]); err != nil {
		return err
	}
	b2 := today.AddDate(0, 0, -40)
	d2 := b2.AddDate(0, 0, 30)
	if _, err := tx.Exec(
		"INSERT INTO borrow_records(reader_id,book_id,borrow_date,due_date,renew_count,status,fine) VALUES(?,?,?,?,?,?,?)",
		readerID, bookID["时间简史"], b2.Format("2006-01-02"), d2.Format("2006-01-02"), 0, "borrowed", 0); err != nil {
		return err
	}
	if _, err := tx.Exec("UPDATE books SET available_qty=available_qty-1 WHERE id=?", bookID["时间简史"]); err != nil {
		return err
	}
	return tx.Commit()
}

var _ = sql.ErrNoRows
